class El:
    _id = 0
    def __init__(self, tag, parent=None):
        El._id += 1
        self.id = El._id
        self.tag = tag
        self.parent = parent

class EventBus:
    def __init__(self):
        self.handlers = []
    def on(self, predicate, cb):
        self.handlers.append((predicate, cb))
    def fire(self, target):
        cur = target
        while cur is not None:
            for pred, cb in self.handlers:
                if pred(cur):
                    cb(cur)
            cur = cur.parent

